// =====================================================================
// scripts/qa/test-pistes-a-qualifier.mjs — « pistes à qualifier » : portée de l'ACTEUR ≠ portée de la PUBLICATION ; signal d'après le TEXTE seul ;
// destination proposée (hub si un territoire est NOMMÉ dans le texte, sinon thématique) ; aucune affaire, aucune fiche ; UNE notification groupée ;
// écriture et envoi exercés avec un `sql` SIMULÉ.
// ⚠ Légendes FICTIVES (paraphrases courtes) : aucun texte réel de tiers. Aucun réseau, aucune base.
// Usage : node scripts/qa/test-pistes-a-qualifier.mjs
// =====================================================================
import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { detecterSignal, pisteDuTexte, construireContexteTerritoire, territoireDuPropos, corpsSansSignature, messagePistes, composerPistes, pisteId, ecrirePiste, envoyerPistes, MOTIFS, LONGUEUR_MESSAGE_MAX } from '../lib/pistes-a-qualifier.mjs';
import { classer, chargerRegistre, parcourirSources, memoireFichier } from '../lib/sources-suivies.mjs';
import { chargerAlias, enrichirFiches } from '../lib/alias-etablissements.mjs';
import { postVersDocument } from '../lib/veille-instagram.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
let ko = 0;
const verifie = (nom, cond, detail = '') => { console.log(`${cond ? '  ✅' : '  ❌'} ${nom}${cond ? '' : ' — ' + detail}`); if (!cond) ko++; };

const reel = JSON.parse(readFileSync(join(ROOT, 'data', 'cases.json'), 'utf8')); const toutes = Array.isArray(reel) ? reel : (reel.cases || reel.affaires);
const ctx = construireContexteTerritoire(toutes, join(ROOT, 'data', 'hub-matiere'));
const reg0 = chargerRegistre(join(ROOT, 'data', 'associations-watchlist.json'));
const avecAlias = enrichirFiches(toutes, chargerAlias(join(ROOT, 'data', 'alias-etablissements.json')));

// Organismes FICTIFS : l'un annonce un territoire (champ hérité d'une version antérieure), l'autre non — le résultat doit être IDENTIQUE
const orga = { id: 'collectif-fictif', nom: 'Collectif fictif – Valmont', alias: ['Collectif fictif', 'Collectif fictif Valmont'], role: 'organisme', portee: 'inconnue', suivi: { domaines: ['instagram.com'] } };
const orgaAvecTerritoire = { ...orga, piste_territoire: { libelle: 'Valmont', motifs: ['PLAINTE_ACCUEIL'] } };
const SIGNATURE = '🖤 Collectif fictif – Valmont';
const doc = (legende, id = 'p1') => postVersDocument({ id_post: id, url: `https://www.instagram.com/p/${id}/`, publie_le: '2026-11-17T10:00:00+0000', legende });
const signal = (legende, o = orga) => detecterSignal({ doc: doc(legende), organisme: o });
const code = (legende, o = orga) => signal(legende, o)?.motif_code || null;

console.log('A. PORTÉES DISTINCTES : le signal vient du TEXTE, jamais du compte ni de la signature');
const plainte = `📣 PLAINTES : NOTRE BILAN\n\nNous, familles du collectif, avons essuyé des refus de plainte à la gendarmerie.\n\n${SIGNATURE}\n\n#valmont #plainte`;
const relaisPresse = `📰 Une famille de notre collectif a témoigné anonymement auprès d'une journaliste, dans un article consacré aux refus de dépôt de plainte.\n\nElle raconte l'accueil qu'elle a reçu à la gendarmerie lorsqu'elle est venue déposer plainte.\n\nMerci à la journaliste.\n\n${SIGNATURE}`;
verifie('déclaration du COMPTE sur les difficultés ou refus de dépôt de plainte (« nous », « notre collectif ») ⇒ PLAINTE_ACCUEIL', code(plainte) === 'PLAINTE_ACCUEIL', JSON.stringify(signal(plainte)));
verifie('UNE MENTION DE PRESSE (article, journaliste) qui parle de refus de plainte ⇒ ARTICLE_PRESSE_CITE, JAMAIS un refus de plainte déclaré', code(relaisPresse) === 'ARTICLE_PRESSE_CITE', code(relaisPresse));
verifie('mention de presse seule (remerciement à une journaliste) ⇒ ARTICLE_PRESSE_CITE ; le mot « plainte » n\'y est pas', code('Merci à la journaliste pour son article.\n\n' + SIGNATURE) === 'ARTICLE_PRESSE_CITE');
verifie('le résultat NE DÉPEND PAS du territoire annoncé par le compte (organisme avec ou sans champ hérité piste_territoire)', ['Merci à la journaliste pour son article.', plainte, relaisPresse, 'Une lettre ouverte sera remise lundi.', 'Merci à toutes et à tous.'].every((l) => code(l, orga) === code(l, orgaAvecTerritoire)));
verifie('SIGNATURE SEULE, hashtags seuls, remerciements, réflexions générales ⇒ AUCUN signal', ['Merci à toutes et à tous pour votre soutien.\n\n' + SIGNATURE, 'La protection des enfants est l\'affaire de tous.\n\n' + SIGNATURE + '\n\n#valmont #plainte #refus #gendarmerie #lettreouverte', SIGNATURE, `Les familles ont besoin d'être accompagnées après un signalement.\n\n${SIGNATURE}`, 'Quels contrôles ? Quelles responsabilités ? Ces questions doivent pouvoir être posées.\n\nNous demandons de la vigilance, de la transparence et des contrôles rigoureux.'].every((l) => signal(l) === null), JSON.stringify(['signature', 'hashtags', 'merci'].map(() => 0)));
verifie('le territoire accolé au nom du compte (« … – Valmont ») est une SIGNATURE : il ne devient pas un lieu du propos', pisteDuTexte({ doc: doc(`Une lettre ouverte sera remise à la mairie lundi.\n\n${SIGNATURE}\n\n#valmont`), organisme: orga, ctx })?.destination === 'THEMATIQUE');
const lettre = 'Nous publions une lettre ouverte : nous demandons la mise en place de quatre mesures et invitons chacun à la co-signer avant dimanche.';
verifie('lettre ouverte / pétition / demande à objet précis ⇒ LETTRE_OU_DEMANDE_PUBLIQUE', code(lettre) === 'LETTRE_OU_DEMANDE_PUBLIQUE' && code('Signez la pétition avant vendredi.') === 'LETTRE_OU_DEMANDE_PUBLIQUE');
verifie('« nous attendons des réponses » SANS événement ni annonce précis (série de questions générales) ⇒ aucun signal ; ANCRÉE dans une annonce ou « après les faits » ⇒ demande publique', code('Les responsabilités doivent être définies. Nous attendons des réponses claires, des engagements concrets.') === null && code('La mairie a annoncé un plan d\'action. Nous prenons acte. Nous attendons des réponses précises : étapes, responsable, évaluation.') === 'LETTRE_OU_DEMANDE_PUBLIQUE' && code('Après les faits survenus, nous attendons des réponses claires sur les mesures mises en place.') === 'LETTRE_OU_DEMANDE_PUBLIQUE');
verifie('appel à témoins ⇒ APPEL_A_TEMOINS ; rassemblement, conférence de presse, saisine ⇒ MOBILISATION_OU_DEMARCHE', code('📣 APPEL À TÉMOINS : contactez-nous.') === 'APPEL_A_TEMOINS' && ['Un rassemblement aura lieu samedi devant la mairie.', 'Nous avons tenu une conférence de presse hier.', 'Nous avons saisi le procureur de la République.', 'Nous avons été reçus par le maire.'].every((l) => code(l) === 'MOBILISATION_OU_DEMARCHE'));
const faussesAlertes = ['Une plainte a été déposée contre un animateur de l\'accueil de loisirs. La gendarmerie mène l\'enquête.', 'La gendarmerie a recueilli la plainte d\'une autre famille.', 'Une plainte collective a été déposée. La police municipale assure l\'accueil à la réunion.', 'Vous pouvez déposer plainte si vous le souhaitez, nous sommes là.', 'Pour toute plainte, contactez les autorités compétentes.'];
verifie('contre-exemples : plainte d\'un tiers, « accueil de loisirs », mots répartis dans des phrases différentes, invitation, rappel ⇒ AUCUN signal PLAINTE_ACCUEIL', faussesAlertes.every((l) => code(l) !== 'PLAINTE_ACCUEIL'), faussesAlertes.filter((l) => code(l) === 'PLAINTE_ACCUEIL').join(' | '));
verifie('la ligne « nom du compte : refus de dépôt de plainte… » n\'est pas retirée comme signature (mais la déclaration doit venir du compte : « nous »)', corpsSansSignature(`${SIGNATURE}\nCollectif fictif : nous avons vu refuser le dépôt de plainte`, orga).includes('refuser le dépôt') && code('Nous avons vu refuser le dépôt de plainte à plusieurs familles. 🖤 Collectif fictif – Valmont') === 'PLAINTE_ACCUEIL');
verifie('témoignage anonyme : écarté AVANT tout (règle actuelle), aucun signal même s\'il parle de plainte refusée ou de journaliste', (() => { const d = doc('✍🏼Témoignage✍🏼 « On m\'a refusé le dépôt de plainte, une journaliste m\'a écouté. »'); return d.ecarte === 'TEMOIGNAGE_ANONYME' && d.corps === '' && detecterSignal({ doc: d, organisme: orga }) === null; })());

// ---- polarité, presse, ancrage, mobilisation (relecture indépendante du 24/11) ----
const polaritesNeg = ['Nous avons été très bien accueillis à la gendarmerie lors de notre plainte.', 'Plusieurs familles ont été prises au sérieux par la gendarmerie lors du dépôt de plainte.', 'Nous rappelons que la police ne peut refuser une plainte : c\'est la loi.', 'Nous demandons que plus aucune famille ne se voie refuser le dépôt de plainte.'];
verifie('POLARITÉ : un accueil FAVORABLE, un rappel de droit ou une revendication ne sont JAMAIS une déclaration de refus de plainte', polaritesNeg.every((l) => code(l) !== 'PLAINTE_ACCUEIL'), polaritesNeg.filter((l) => code(l) === 'PLAINTE_ACCUEIL').join(' | '));
verifie('accueil DÉFAVORABLE déclaré par le compte (« nous avons été mal accueillis ») ⇒ PLAINTE_ACCUEIL', code('Nous avons été mal accueillis à la gendarmerie lors de notre plainte.') === 'PLAINTE_ACCUEIL');
const presseAttribuee = ['Plusieurs familles se sont vu refuser le dépôt de plainte, selon Le Télégramme.', 'Des familles auraient vu refuser le dépôt de plainte, d\'après France 3.', 'Notre collectif a vu refuser le dépôt de plainte, rapporte La Nouvelle République.'];
verifie('PRESSE par attribution (« selon … », « d\'après … », « rapporte … ») ⇒ jamais un refus de plainte déclaré par le compte : ARTICLE_PRESSE_CITE', presseAttribuee.every((l) => code(l) === 'ARTICLE_PRESSE_CITE'), presseAttribuee.map((l) => code(l)).join());
verifie('« tout le monde » n\'est pas « Le Monde » : aucun signal de presse ; et une vraie déclaration commençant par « Tout le monde doit savoir » reste PLAINTE_ACCUEIL', code('Merci à tout le monde pour le vide-grenier.') === null && code('Tout le monde doit savoir : nous avons vu refuser le dépôt de plainte.') === 'PLAINTE_ACCUEIL');
verifie('le « nous » d\'une phrase de presse ne franchit pas la phrase suivante', code('Nous avons rencontré une journaliste de France Info. Les familles ont été mal accueillies à la gendarmerie lors de leur plainte.') !== 'PLAINTE_ACCUEIL');
verifie('ANCRAGE : « nous attendons des réponses » après « merci à ceux qui ont publié notre message » ou « une réunion est prévue » ⇒ AUCUN signal (mots banals)', code('Merci à ceux qui ont publié notre message. Nous attendons des réponses.') === null && code('Une réunion est prévue lundi. Nous attendons des réponses.') === null);
verifie('MOBILISATION : « communiqué » nu et « rencontre avec des parents » ⇒ aucun signal ; « nous avons rencontré le maire » ⇒ démarche auprès d\'une institution', code('Communiqué : la cantine sera fermée lundi.') === null && code('Nous avons rencontré les parents.') === null && code('Nous avons rencontré le maire de la commune.') === 'MOBILISATION_OU_DEMARCHE');

console.log('B. Territoire du PROPOS : nommé dans le texte ou absent ; jamais déduit du compte');
const T = (texte) => territoireDuPropos(texte, ctx);
verifie('« Tarnos » dans le texte ⇒ territoire Tarnos, hub « landes » ; « Mées » et « Landes » aussi', T('Après les faits survenus à Tarnos, nous attendons des réponses.')?.hub_id === 'landes' && T('Une réunion publique à Mées.')?.hub_id === 'landes' && T('Dans les Landes, des familles disent…')?.hub_id === 'landes' && T('Après les faits à Tarnos')?.libelle === 'Tarnos');
verifie('aucun lieu dans le texte ⇒ aucun territoire (piste thématique), même si le compte se nomme « … – Tarnos »', T('La mairie a annoncé un plan d\'action pour la protection de l\'enfance.') === null && T(corpsSansSignature('Lettre ouverte à la mairie.\n\nLeurs voix, notre combat – Tarnos\n#tarnos', { nom: 'Leurs voix, notre combat – Tarnos', alias: ['Leurs voix, notre combat'] })) === null);
verifie('« Dax » seul (commune sans fiche SNY) ⇒ pas de territoire reconnu : on n\'en déduit pas « Landes »', T('Certaines familles ont dû se déplacer jusqu\'à Dax pour déposer plainte.') === null);
verifie('Paris GÉNÉRAL (« Mairie de Paris », « écoles parisiennes », « parents du 10ème ») ⇒ territoire « Paris », AUCUN hub : jamais « Paris 11e »', (() => { const t = T('Dans les écoles parisiennes, les parents du 10ème et la Mairie de Paris…'); return t?.libelle === 'Paris' && t.hub_id === null && t.niveau === 'ville'; })());
verifie('« Paris 11e » / « 11e arrondissement » NOMMÉ dans le texte ⇒ hub « paris-11e »', T('Dans le 11e arrondissement de Paris, une école…')?.hub_id === 'paris-11e' && T('école de Paris 11e')?.hub_id === 'paris-11e');
verifie('les hubs « isolés » ne sont pas des hubs de territoire : aucun hub « isoles » dans la couverture', !ctx.hubs.some((h) => h.hub_id === 'isoles') && ctx.hubs.some((h) => h.hub_id === 'landes') && ctx.hubs.some((h) => h.hub_id === 'paris-11e'));
const lettreParis = 'Lettre ouverte à la maire de Paris : les parents du 10ème et notre association demandent la mise en place de quatre mesures dans le périscolaire des écoles parisiennes.';
const pParis = pisteDuTexte({ doc: doc(lettreParis), organisme: { ...orga, id: 'sos', nom: 'SOS fictif', alias: ['SOS fictif'] }, ctx });
verifie('action générale d\'un acteur à portée Paris (lettre à la Ville) ⇒ piste HUB « Paris » SANS hub, jamais attribuée à Paris 11e', pParis?.destination === 'HUB' && pParis.territoire === 'Paris' && pParis.hub_id === null && !/11e/.test(pParis.classement) && /aucun hub ne couvre ce territoire/.test(pParis.classement), JSON.stringify(pParis));
const pTarnos = pisteDuTexte({ doc: doc('Après les faits survenus à Tarnos, nous attendons des réponses claires sur les mesures mises en place.'), organisme: orga, ctx });
const pSans = pisteDuTexte({ doc: doc('La mairie a annoncé un plan d\'action. Nous attendons des réponses précises : étapes, responsable.'), organisme: orga, ctx });
verifie('texte qui NOMME Tarnos ⇒ destination HUB « landes » ; texte sans lieu ⇒ THEMATIQUE sans territoire ; le motif du classement est conservé', pTarnos?.destination === 'HUB' && pTarnos.hub_id === 'landes' && /lu dans le texte/.test(pTarnos.classement) && pSans?.destination === 'THEMATIQUE' && pSans.territoire === null && /sans territoire/.test(pSans.classement), JSON.stringify([pTarnos, pSans]));

// ---- territoire : faux territoires, 11e, signature (relecture indépendante du 24/11) ----
verifie('PARIS 11e seulement si le texte l\'écrit : « Paris, 11 décembre » et « 11e arrondissement de Lyon » ⇒ « Paris » sans 11e, jamais le hub paris-11e', T('Rassemblement à Paris, 11 décembre.')?.libelle === 'Paris' && T('Rassemblement à Paris, devant l\'école du 11e arrondissement de Lyon.')?.libelle === 'Paris' && T('Rassemblement à Paris, 11 décembre.')?.hub_id === null);
verifie('FAUX TERRITOIRES : « Le Parisien » (journal), « chacun sache », « Orange » (opérateur), « la réunion de la semaine » ⇒ aucun territoire', T('Selon Le Parisien, une lettre ouverte a été publiée.') === null && T('Afin que chacun sache ce qui s\'est passé.') === null && T('Nous avons écrit à Orange et à d\'autres opérateurs.') === null && T('Nous vous attendons à la réunion de la semaine dernière.') === null);
verifie('un nom de média porteur d\'un lieu (« Nice-Matin ») ne devient pas le territoire du propos', T('Merci à Nice-Matin pour son article.') === null);
const orgReel = reg0.organismes.find((o) => o.id === 'leurs-voix-notre-combat-tarnos');
const terr = (l) => pisteDuTexte({ doc: doc(l), organisme: orgReel, ctx })?.destination;
verifie('SIGNATURE « – Tarnos » sur la même ligne, entre parenthèses ou en « depuis Tarnos » ⇒ jamais un lieu du propos (piste THÉMATIQUE) ; « Tarnos » écrit DANS le texte ⇒ hub', ['Une lettre ouverte sera remise lundi. Leurs voix, notre combat – Tarnos', '🖤 Collectif Leurs voix, notre combat – Tarnos (40)\nUne lettre ouverte sera remise lundi.', 'Une lettre ouverte sera remise lundi.\nLeurs voix, notre combat, depuis Tarnos 🖤'].every((l) => terr(l) === 'THEMATIQUE') && terr('Une lettre ouverte sera remise à la mairie de Tarnos lundi.\n\nLeurs voix, notre combat – Tarnos') === 'HUB');

console.log('C. Classement : une piste n\'est ni une affaire ni un rattachement ; l\'affaire passe avant');
const classe = (legende, o = orga, liste = avecAlias, extraction = true) => { const d = doc(legende); if (!extraction) d.extraction = 'html'; return classer({ doc: d, page: { url: 'https://www.instagram.com/c/', type: 'document' }, organisme: o, fiches: liste }); };
let c = classe(plainte);
verifie('signal sans lieu ni affaire ⇒ PISTE_A_QUALIFIER, destination THEMATIQUE ; case_ids et suspendus VIDES ; compte sans aucun territoire annoncé', c.destination === 'PISTE_A_QUALIFIER' && c.piste.destination === 'THEMATIQUE' && c.case_ids.length === 0 && c.suspendus.length === 0, JSON.stringify(c));
verifie('le motif du classement dit le signal, la destination et « aucun rattachement à une affaire »', /aucun territoire dans le texte lu/.test(c.motif) && /aucun rattachement à une affaire/.test(c.motif));
c = classe('Après les faits survenus à Tarnos, nous attendons des réponses claires sur la protection de l\'enfance et les mesures mises en place.');
verifie('texte qui nomme Tarnos (sans la structure ni le rôle) ⇒ piste HUB « landes », JAMAIS une affaire', c.destination === 'PISTE_A_QUALIFIER' && c.piste.destination === 'HUB' && c.piste.hub_id === 'landes' && c.case_ids.length === 0);
c = classe('📣 APPEL À TÉMOINS — votre enfant a fréquenté le centre de loisirs de Tarnos ? Vous pouvez effectuer un signalement.');
verifie('texte qui nomme la STRUCTURE par son alias propre ⇒ « affaire à confirmer » (passe AVANT la piste) ; jamais les deux signaux', c.destination === 'AFFAIRE_A_CONFIRMER');
c = classe('Un animateur périscolaire du centre de loisirs de Tarnos a été mis en examen : nous restons mobilisés.');
verifie('lien DÉMONTRÉ par le texte (structure, commune, rôle) ⇒ AFFAIRE, pas une piste', c.destination === 'AFFAIRE' && c.case_ids.join() === 'FR-2026-0115', JSON.stringify(c));
verifie('signature seule (avec le territoire du compte) ⇒ jamais PISTE_A_QUALIFIER', ['Merci à toutes et à tous.\n\n' + SIGNATURE, `Soutien aux familles.\n\n${SIGNATURE}\n\n#valmont #plainte`].every((l) => classe(l).destination !== 'PISTE_A_QUALIFIER'));
verifie('même texte hors compte Instagram (document HTML) ⇒ jamais PISTE_A_QUALIFIER', classe(plainte, orga, avecAlias, false).destination !== 'PISTE_A_QUALIFIER');
verifie('lettre ouverte à la Ville de Paris ⇒ jamais rattachée à une affaire de Paris 11e (ni AFFAIRE, ni suspendu) ; piste HUB « Paris » sans hub', (() => { const r = classe(lettreParis, { ...orga, id: 'sos', nom: 'SOS fictif', alias: ['SOS fictif'] }); return r.destination === 'PISTE_A_QUALIFIER' && r.piste.hub_id === null && r.case_ids.length === 0 && r.suspendus.length === 0; })());

// ---- publications PROPRES d'un acteur suivi (blog, communiqué, pétition) : déclaration d'ensemble de plusieurs écoles, exposants, presse référencée ----
const declEnsemble = 'Nous, parents d\'élèves de plusieurs écoles du 11ᵉ arrondissement de Paris, avons saisi le Défenseur des droits le 22 décembre 2025 au sujet des violences sexuelles dans le périscolaire. Signataires : parents des écoles maternelles Alphonse Baudin, Bullourde et Faidherbe.';
const classeDoc = (corps, { propre = true, o = { ...orga, pistes_propres: true }, fiches = avecAlias } = {}) => classer({ doc: { ok: true, url: 'https://blog.example.invalid/billet', url_finale: 'https://blog.example.invalid/billet', publie_le: '2026-01-28', titre: 'Billet', corps, extraction: 'html' }, page: { url: 'https://blog.example.invalid/', type: 'document' }, organisme: o, fiches, pisteOuverte: propre });
const rEns = classeDoc(declEnsemble);
verifie('DÉCLARATION D\'ENSEMBLE d\'un acteur suivi (plusieurs écoles nommées, « 11ᵉ » en exposant) ⇒ piste HUB paris-11e, AUCUN case_id, AUCUN rattachement suspendu à plusieurs affaires', rEns.destination === 'PISTE_A_QUALIFIER' && rEns.piste.motif_code === 'MOBILISATION_OU_DEMARCHE' && rEns.piste.destination === 'HUB' && rEns.piste.hub_id === 'paris-11e' && rEns.case_ids.length === 0 && rEns.suspendus.length === 0 && rEns.structures_nommees >= 2, JSON.stringify(rEns));
verifie('le MÊME texte reste un rattachement SUSPENDU (jamais une piste) quand le document n\'est pas une publication propre de l\'acteur (article de presse référencé)', classeDoc(declEnsemble, { propre: false }).destination === 'RATTACHEMENT_SUSPENDU', classeDoc(declEnsemble, { propre: false }).destination);
const declRoles = 'Un animateur périscolaire de l\'école maternelle Alphonse-Baudin (Paris 11e) et un animateur périscolaire de l\'école maternelle Bullourde (Paris 11e) ont été suspendus pour des violences sexuelles. Nous, parents, avons saisi le Défenseur des droits.';
const rRoles = classeDoc(declRoles);
verifie('DEUX écoles nommées AVEC leur rôle (rattachements pleins possibles, base de production qui contient plus de fiches) ⇒ toujours une déclaration d\'ensemble : piste HUB, aucun case_id ; hors publication propre ⇒ jamais une piste', rRoles.destination === 'PISTE_A_QUALIFIER' && rRoles.case_ids.length === 0 && rRoles.piste.hub_id === 'paris-11e' && classeDoc(declRoles, { propre: false }).destination !== 'PISTE_A_QUALIFIER', JSON.stringify(rRoles));
// Chemin RÉEL d'une page « document » du registre (constat du dry-run CI du 26/11 : la porte pisteOuverte n'était pas passée à ce chemin-là)
{
  const page = { url: 'https://blog.example.invalid/billet', type: 'document', cadence: 'hebdomadaire', emetteur: 'Parents fictifs (blog)', organismes: ['parents-fictifs'] };
  const registre = { organismes: [{ id: 'parents-fictifs', nom: 'Parents fictifs', alias: ['Parents fictifs'], role: 'organisme', portee: 'inconnue', pistes_propres: true, suivi: { domaines: ['blog.example.invalid'], pages: [page] } }], pages: [page] };
  const lire = async (url) => ({ ok: true, url, url_finale: url, publie_le: '2026-01-28', titre: 'Billet', corps: declEnsemble, extraction: 'html', statut_http: 200 });
  const r = await parcourirSources({ registre, memoire: memoireFichier('/inexistant/m.json', { lectureSeule: true }), fiches: avecAlias, lire, lireRss: async () => ({ ok: false, items: [] }), maintenant: '2026-11-26T10:00:00Z' });
  const l = r.pages.find((p) => p.url === page.url);
  verifie('PAGE « document » du registre (chemin réel de parcourirSources) : déclaration d’ensemble d’un acteur suivi ⇒ PISTE_A_QUALIFIER (hub paris-11e), jamais un rattachement suspendu', l?.destination === 'PISTE_A_QUALIFIER' && l.piste?.hub_id === 'paris-11e' && l.case_ids.length === 0, JSON.stringify({ d: l?.destination, p: l?.piste?.hub_id }));
}
